parameters.jsCode:
// Decides which nurture email is due today.
//
// The sequence is three CONSECUTIVE CALENDAR DAYS from the lead's creation
// date: day 0 email 1 (sent by the CoachMatch lead workflow, not here),
// day 1 email 2, day 2 email 3. Calendar days, not business days.
//
// Changed September 2, 2026 -- this used elapsed hours (>= 24 / >= 48) against
// a 09:00 trigger, so any lead created after 09:00 missed its window by a few
// hours and slipped a full day: a 14:00 lead got email 2 on day 2 and email 3
// on day 3. Comparing calendar dates instead makes the boundary the thing the
// sequence is actually defined by.
//
// Day boundaries are America/Cordoba (UTC-3). Argentina has had no DST since
// 2009, so shifting the timestamp by -3h and reading its UTC date is exact and
// needs no timezone database.
const AR_OFFSET_MS = 3 * 60 * 60 * 1000;
const arDate = (d) => new Date(d.getTime() - AR_OFFSET_MS).toISOString().slice(0, 10);
const daysBetween = (a, b) =>
  Math.round((Date.parse(arDate(b)) - Date.parse(arDate(a))) / 86400000);

const now = new Date();
const results = [];

for (const edge of $input.first().json.data.people.edges) {
  const person = edge.node;
  const touchCount = person.emailTouchCount;

  // Which email this lead should be at today: 1 on the day it arrived, 2 the
  // next calendar day, 3 the day after. Capped at 3 -- there is no email 4.
  // Expressed as "which email is due" rather than "has enough time passed" so
  // that a second run on the same day sends nothing (touchCount already equals
  // the expected number) and a missed day resumes at the next email in
  // sequence instead of skipping one.
  const expected = Math.min(daysBetween(new Date(person.createdAt), now) + 1, 3);
  const isDue = touchCount >= 1 && touchCount < expected;

  if (isDue) {
    results.push({
      json: {
        id: person.id,
        firstname: person.name.firstName,
        lastname: person.name.lastName,
        email: person.emails.primaryEmail,
        emailTouchCount: touchCount,
        preferredLanguage: person.preferredLanguage || null
      }
    });
  }
}

return results;

return [{
  json: {
    query: "mutation UpdatePerson($id: ID!, $data: PersonUpdateInput!) { updatePerson(id: $id, data: $data) { id } }",
    variables: {
      id: $('Code in JavaScript').item.json.id,
      data: {
        emailTouchCount: 2,
        lastTouchpoint: new Date().toISOString()
      }
    }
  }
}];

return [{
